export async function openDirectoryPicker(): Promise<FileSystemDirectoryHandle> {
  return await window.showDirectoryPicker({
    mode: 'read',
    startIn: 'documents'
  })
}

export async function* walkDirectory(
  handle: FileSystemDirectoryHandle,
  path: string[] = []
): AsyncGenerator<{ path: string[], handle: FileSystemFileHandle }> {
  for await (const entry of handle.values()) {
    if (entry.kind === 'file') {
      yield { path: [...path, entry.name], handle: entry }
    } else if (entry.kind === 'directory') {
      yield* walkDirectory(entry, [...path, entry.name])
    }
  }
}

export async function readFile(handle: FileSystemFileHandle): Promise<string> {
  const file = await handle.getFile()
  return file.text()
}
