## Implementation
Use webkitGetAsEntry() API for Firefox/Safari support:

```typescript
// In fileSystem.ts
export async function readDroppedDirectory(
  entry: FileSystemDirectoryEntry
): Promise<Map<string, string>> {
  const files = new Map<string, string>()

  async function readEntry(entry: FileSystemEntry, path: string) {
    if (entry.isFile) {
      const file = await new Promise<File>((resolve, reject) => {
        (entry as FileSystemFileEntry).file(resolve, reject)
      })
      files.set(path, await file.text())
    } else if (entry.isDirectory) {
      const reader = (entry as FileSystemDirectoryEntry).createReader()
      const entries = await new Promise<FileSystemEntry[]>((resolve, reject) => {
        reader.readEntries(resolve, reject)
      })
      for (const child of entries) {
        await readEntry(child, path + '/' + child.name)
      }
    }
  }

  await readEntry(entry, entry.name)
  return files
}
```

