```typescript
export function buildSessionTree(
  sessions: Map<string, SessionInfo>
): SessionNode[] {
  const nodes = new Map<string, SessionNode>()

  // Create nodes for all sessions
  for (const session of sessions.values()) {
    nodes.set(session.id, { session, children: [] })
  }

  // Link children to parents
  const roots: SessionNode[] = []
  for (const node of nodes.values()) {
    const parentId = node.session.parentID
    if (parentId && nodes.has(parentId)) {
      nodes.get(parentId)!.children.push(node)
    } else {
      roots.push(node)
    }
  }

  // Sort: children by creation time, roots by most recent
  function sortNode(node: SessionNode) {
    node.children.sort((a, b) => 
      a.session.time.created - b.session.time.created
    )
    node.children.forEach(sortNode)
  }
  roots.forEach(sortNode)
  roots.sort((a, b) => b.session.time.updated - a.session.time.updated)

  return roots
}
```

## Edge Cases
- Orphaned children (parentID points to non-existent session) → treat as root
- Deep nesting (agent spawns agent spawns agent) → works recursively
- Circular references → detect and break

## Acceptance Criteria
- Sessions with parentID appear as children
- Orphaned children appear at root level
- Proper sorting (recent first for roots, chronological for children)
- No infinite loops on circular references

