export async function loadSessionContent(
  sessionId: string,
  fs: VirtualFileSystem
): Promise<Session> {
  // 1. Read session info (may already be cached)
  const info = await loadSessionInfo(sessionId, fs)

  // 2. List and load all messages from message/<sessionId>/
  const messageIds = await fs.listDirectory(['message', sessionId])
  const messages: Message[] = []

  for (const msgFile of messageIds) {
    const msgId = msgFile.replace('.json', '')
    const msgJson = await fs.readFile(['message', sessionId, msgFile])
    const msgInfo = JSON.parse(msgJson)

    // 3. Load parts for this message from part/<messageId>/
    const partIds = await fs.listDirectory(['part', msgId])
    const parts: Part[] = []
    for (const partFile of partIds) {
      const partJson = await fs.readFile(['part', msgId, partFile])
      parts.push(JSON.parse(partJson))
    }

    messages.push({ info: msgInfo, parts })
  }

  // 4. Sort messages by creation time
  messages.sort((a, b) => a.info.time.created - b.info.time.created)

  return { info, messages }
}
```

