## Goal
When 'Include user messages' is toggled, search through message content.

## Implementation
Option 1: Load all messages upfront (more memory, faster search)
Option 2: Search on-demand (less memory, slower search)

Recommend Option 1 for reasonable session counts (<1000):
```typescript
interface SessionWithMessages extends SessionInfo {
  userMessages: string[]  // Extracted text from user messages
}

// During initial load, also extract user message text
async function loadSessionWithMessages(sessionId, fs): Promise<SessionWithMessages> {
  const info = await loadSessionInfo(sessionId, fs)
  const messageFiles = await fs.listDirectory(['message', sessionId])

  const userMessages: string[] = []
  for (const file of messageFiles) {
    const msg = JSON.parse(await fs.readFile(['message', sessionId, file]))
    if (msg.role === 'user') {
      // Extract text from text parts
      const parts = await loadPartsForMessage(msg.id, fs)
      const text = parts
        .filter(p => p.type === 'text')
        .map(p => p.text)
        .join(' ')
      userMessages.push(text)
    }
  }

  return { ...info, userMessages }
}
```

